"""
Lab solution: Build a Research Report Auditor
Standard library only.
"""
import re
from urllib.parse import urlparse

REQUIRED_FIELDS = ["question", "scope", "sources", "time_range", "deliverable"]
VAGUE_TIME_WORDS = {"latest", "recent", "recently", "current", "currently", "new"}
STRONG_SUFFIXES = (".gov", ".edu", ".ac.uk", ".gov.in")


def normalise(text):
    """Lower-case and collapse whitespace."""
    return re.sub(r"\s+", " ", text.lower()).strip()


def word_set(text):
    """The set of lower-case words in a text."""
    return set(re.findall(r"[a-z0-9]+", text.lower()))


# ---------------------------------------------------------------- Step 1
def validate_brief(brief):
    """A deep research run is scarce and slow. Catch an incomplete brief before spending one.

    "Latest" and "recent" mean nothing to a system with no fixed sense of today: give dates.
    """
    problems = [f"missing:{field}" for field in REQUIRED_FIELDS
                if not str(brief.get(field) or "").strip()]
    question_words = word_set(str(brief.get("question") or ""))
    problems += [f"vague:{word}" for word in VAGUE_TIME_WORDS if word in question_words]
    return sorted(problems)


# ---------------------------------------------------------------- Step 2
def source_score(url, year, current_year=2026):
    """A crude proxy for sorting sources so the weakest get looked at first. Not a verdict.

    Testing the END of the host name avoids being fooled by ".gov" elsewhere in a URL.
    """
    host = urlparse(url).netloc.lower()
    if host.endswith(STRONG_SUFFIXES):
        score = 3
    elif host.endswith(".org"):
        score = 2
    else:
        score = 1
    if current_year - year > 3:
        score -= 1
    return max(score, 0)


# ---------------------------------------------------------------- Step 3
def check_citations(claims, sources):
    """A citation existing is not a citation supporting. This checks the second thing.

    Three outcomes: a missing source is often a fabricated or broken link; a quote that
    is not in an existing source is a misreading or misattribution.
    """
    statuses = []
    for claim in claims:
        source_text = sources.get(claim["source_id"])
        if source_text is None:
            statuses.append("missing_source")
        elif normalise(claim["quote"]) in normalise(source_text):
            statuses.append("supported")
        else:
            statuses.append("not_found")
    return statuses


# ---------------------------------------------------------------- Step 4
def citation_accuracy(statuses):
    """Supported claims divided by claims checked."""
    if not statuses:
        return 0.0
    return statuses.count("supported") / len(statuses)


# ---------------------------------------------------------------- Step 5
def independent_sources(sources, threshold=0.8):
    """Five citations of one press release are one source.

    Sorted order makes the result reproducible: the first of a duplicate group is kept.
    """
    kept = []
    for source_id in sorted(sources):
        words = word_set(sources[source_id])
        duplicate = False
        for other in kept:
            other_words = word_set(sources[other])
            union = words | other_words
            if union and len(words & other_words) / len(union) >= threshold:
                duplicate = True
                break
        if not duplicate:
            kept.append(source_id)
    return kept


if __name__ == "__main__":
    print(validate_brief({"question": "What's the latest on AI regulation?"}))
    print(validate_brief({
        "question": "Which binding obligations apply to consumer AI chat assistants in the EU?",
        "scope": "EU only; laws in force; deployers.",
        "sources": "Official legal texts and regulator guidance.",
        "time_range": "Position as of 1 November 2026.",
        "deliverable": "A table of obligations with effective dates and sources.",
    }))

    for url, year in (("https://www.census.gov/data/report", 2025), ("https://example.org/study", 2024),
                      ("https://someblog.example.com/post", 2020)):
        print(f"{source_score(url, year)}  {url} ({year})")

    sources = {
        "S1": "The refurbished smartphone market in India grew 19 percent in 2024,\n according to the annual survey.",
        "S2": "Analysts expect the segment to reach 12 billion dollars by 2028.",
    }
    claims = [
        {"quote": "grew 19 percent in 2024", "source_id": "S1"},
        {"quote": "reach 12 billion dollars by 2028", "source_id": "S2"},
        {"quote": "grew 29 percent in 2024", "source_id": "S1"},
        {"quote": "exports doubled", "source_id": "S9"},
    ]
    statuses = check_citations(claims, sources)
    print(statuses, f"-> citation accuracy {citation_accuracy(statuses):.2f}")

    wire = {"A": "Sales of refurbished phones rose sharply in 2024, the company said on Tuesday.",
            "B": "Sales of refurbished phones rose sharply in 2024, the company said on Tuesday. Read more.",
            "C": "An independent survey of 4,000 buyers found demand was flat."}
    print("independent sources:", independent_sources(wire), "of", len(wire))
